def candies(M: int, N: int) -> int:
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    if gcd(M, N) != 1:
        return 0

    limit = M * N - M - N
    dp = [False] * (limit + 1)

    for i in range(0, limit + 1, M):
        dp[i] = True
    for i in range(0, limit + 1, N):
        dp[i] = True

    for i in range(M + N, limit + 1):
        if not dp[i]:
            dp[i] = dp[i - M] or dp[i - N]

    return sum(not x for x in dp)
